head.b:skin:
/*
-----------------------------------------------
Name:   Farcodo Arabic
Version: 2.0.0
Notes:  Original RTL Arabic template for Farcodo.
-----------------------------------------------
<Variable name="brand.navy" description="اللون الكحلي" type="color" default="#0a1a3f" value="#0a1a3f"/>
<Variable name="brand.blue" description="الأزرق الكهربائي" type="color" default="#0a5cff" value="#0a5cff"/>
<Variable name="brand.cyan" description="السماوي" type="color" default="#00c8ff" value="#00c8ff"/>
<Variable name="footer.bg" description="خلفية التذييل" type="color" default="#07122e" value="#07122e"/>
<Variable name="layout.width" description="أقصى عرض للمحتوى" type="length" default="1240px" min="960px" max="1500px" value="1240px"/>
<Variable name="card.radius" description="استدارة البطاقات" type="length" default="16px" min="0px" max="28px" value="16px"/>
*/
/* Farcodo Arabic — original stylesheet. RTL-first, logical properties. */
:root{--blue:$(brand.blue);--cyan:$(brand.cyan);--navy:$(brand.navy);
--bg:#f5f7fb;--surface:#fff;--ink:#0d1b3a;--muted:#55627f;--line:#e1e7f2;--link:#0a4fe0;--wm:var(--navy);
--grad:linear-gradient(135deg,var(--blue) 0%,var(--cyan) 100%);
--shadow:0 8px 28px rgba(10,26,63,.08);--r:$(card.radius);--max:$(layout.width);--hh:68px;
--font:'IBM Plex Sans Arabic','Segoe UI',Tahoma,'Noto Naskh Arabic',Arial,sans-serif;
--sym:url("data:image/webp;base64,")}
[data-theme=dark]{--bg:#0a1020;--surface:#111a30;--ink:#e9eefb;--muted:#a3b2d4;--line:#22305a;--link:#6fb3ff;--wm:#fff;--shadow:0 8px 28px rgba(0,0,0,.45)}
/* Dark theme contrast fix: theme state lives on html, so explicitly recolor surfaces and all header text. */
html[data-theme=dark],
html[data-theme=dark] body{background:#0a1020!important;color:#e9eefb!important;color-scheme:dark}
html[data-theme=dark] .fc-header,
html[data-theme=dark] .fc-main-wrap,
html[data-theme=dark] .fc-wrap,
html[data-theme=dark] .fc-layout,
html[data-theme=dark] #fc-main,
html[data-theme=dark] .fc-listhead,
html[data-theme=dark] .fc-pagebox,
html[data-theme=dark] .fc-archive,
html[data-theme=dark] .fc-searchbox,
html[data-theme=dark] .fc-footer,
html[data-theme=dark] .fc-bottom{background-color:#0a1020!important;color:#e9eefb!important}
html[data-theme=dark] .fc-header{background:rgba(10,16,32,.96)!important;border-color:#263653}
/* Dark mode polish: continuous bands and balanced footer alignment. */
html[data-theme=dark] .fc-wrap{background:transparent!important;color:#e9eefb!important}
html[data-theme=dark] .fc-top,
html[data-theme=dark] .fc-topbar,
html[data-theme=dark] .topbar{background:#082f46!important;color:#e9eefb!important}
html[data-theme=dark] .fc-footer{background:#082f46!important;color:#d8e5f7!important}
html[data-theme=dark] .fc-footer .fc-wrap,
html[data-theme=dark] .fc-footer .fc-foot-grid,
html[data-theme=dark] .fc-footer .fc-bottom{background:transparent!important}
html[data-theme=dark] .fc-footer .fc-brand{justify-content:flex-start;align-items:center;gap:8px;margin-inline-start:0;padding-inline:0}
html[data-theme=dark] .fc-footer .fc-brand img{margin-inline-end:0}
html[data-theme=dark] .fc-footer .fc-foot-grid{align-items:start}
html[data-theme=dark] .fc-footer .fc-copyright{align-items:center}

html[data-theme=dark] .fc-brand,
html[data-theme=dark] .fc-home-link,
html[data-theme=dark] .fc-nav a,
html[data-theme=dark] .fc-drawer-nav a,
html[data-theme=dark] .fc-sec-t,
html[data-theme=dark] .fc-title,
html[data-theme=dark] .fc-listhead h1,
html[data-theme=dark] .fc-pagebox h1,
html[data-theme=dark] .fc-pagebox h2,
html[data-theme=dark] .fc-pagebox h3,
html[data-theme=dark] .fc-pagebox p,
html[data-theme=dark] .fc-card,
html[data-theme=dark] .fc-card p,
html[data-theme=dark] .fc-sec-sub,
html[data-theme=dark] .fc-article .post-body,
html[data-theme=dark] .fc-copyright{color:#e9eefb!important}
html[data-theme=dark] .fc-card,
html[data-theme=dark] .fc-state,
html[data-theme=dark] .fc-tw,
html[data-theme=dark] .fc-comments,
html[data-theme=dark] .fc-related,
html[data-theme=dark] .widget,
html[data-theme=dark] .fc-clist{background-color:#111a30!important;color:#e9eefb!important;border-color:#2b3a58!important}
html[data-theme=dark] input,
html[data-theme=dark] select,
html[data-theme=dark] textarea,
html[data-theme=dark] .search-form input,
html[data-theme=dark] .fc-search{background:#111a30!important;color:#e9eefb!important;border-color:#34435f!important}
html[data-theme=dark] input::placeholder,
html[data-theme=dark] textarea::placeholder{color:#bdc9df!important;opacity:1}
html[data-theme=dark] a{color:#8bc5ff}
html[data-theme=dark] .fc-banner{color:#fff!important}
/* Dark-mode contrast for the homepage callout: “خلّيك في قلب التقنية”. */
html[data-theme=dark] .fc-start-wrap{color:#e9eefb!important}
/* Correct the actual cause of the faded callout: its light gradient was remaining in dark mode. */
html[data-theme=dark] .fc-start{
  background:#111a30!important;
  background-image:none!important;
  border-color:#2b3a58!important;
  box-shadow:0 8px 24px rgba(0,0,0,.22)!important;
}
html[data-theme=dark] body .fc-start h2,
html[data-theme=dark] body #fc-start-title,
html[data-theme=dark] body .fc-start-copy h2{color:#f4f7ff!important;opacity:1!important;-webkit-text-fill-color:#f4f7ff!important}
html[data-theme=dark] body .fc-start p,
html[data-theme=dark] body .fc-start-copy p{color:#c7d5ea!important;opacity:1!important;-webkit-text-fill-color:#c7d5ea!important}
html[data-theme=dark] .fc-start .btn,
html[data-theme=dark] .fc-start .btn-p{background:linear-gradient(110deg,#0878ff,#00b8f4)!important;color:#fff!important;opacity:1!important}
html[data-theme=dark] .fc-start .btn svg{color:#fff!important;opacity:1!important}

html[data-theme=dark] .fc-start,
html[data-theme=dark] .fc-start-copy,
html[data-theme=dark] #fc-start-title,
html[data-theme=dark] .fc-start-copy h2{color:#e9eefb!important}
html[data-theme=dark] .fc-start-copy p{color:#c7d5ea!important;opacity:1!important}
html[data-theme=dark] .fc-start .btn,
html[data-theme=dark] .fc-start .btn-p{color:#fff!important;opacity:1!important}
html[data-theme=dark] .fc-start .btn svg{color:#fff!important;opacity:1!important}

html[data-theme=dark] .fc-footer a,
html[data-theme=dark] .fc-bottom a{color:#d9e8ff!important}

*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--hh) + 16px);-webkit-text-size-adjust:100%}
body{margin:0;font:400 17px/1.8 var(--font);background:var(--bg);color:var(--ink);text-rendering:optimizeLegibility}
body.fc-lock{overflow:hidden}
img,svg,video{max-width:100%}
a{color:var(--link);text-decoration:none}
a:hover{text-decoration:underline}
:focus-visible{outline:3px solid var(--cyan);outline-offset:2px;border-radius:6px}
.sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:absolute;inset-inline-start:12px;top:-60px;z-index:200;background:var(--navy);color:#fff;padding:10px 16px;border-radius:10px}
.skip:focus{top:10px;text-decoration:none}
.fc-wrap{width:100%;max-width:var(--max);margin-inline:auto;padding-inline:20px}
.ico{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}

/* Header */
.fc-header{position:sticky;top:0;z-index:100;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:saturate(1.4) blur(12px);border-bottom:1px solid var(--line)}
.fc-hdr{display:flex;align-items:center;gap:20px;min-height:var(--hh)}
.fc-brand{display:inline-flex;align-items:center;direction:ltr;gap:0;font:700 30px/1 var(--font);letter-spacing:-.01em;color:var(--wm);text-decoration:none!important;white-space:nowrap}
.fc-brand img{height:1.04em;width:auto;display:block;aspect-ratio:891/877;flex-shrink:0;margin-inline-end:-.11em}
.fc-brand span{display:block}
.fc-home-link{display:block;padding:8px 14px;border-radius:999px;color:var(--ink);font-weight:600;font-size:16px;white-space:nowrap}
.fc-home-link:hover{background:color-mix(in srgb,var(--blue) 10%,transparent);text-decoration:none}
.fc-nav{flex:1;min-width:0}
.fc-nav ul{display:flex;gap:4px;list-style:none;margin:0;padding:0;flex-wrap:wrap}
.fc-nav li{position:relative}
.fc-nav li ul{display:none;position:absolute;top:100%;right:0;min-width:190px;z-index:120;flex-direction:column;flex-wrap:nowrap;gap:2px;padding:8px;background:var(--surface);border:1px solid var(--line);border-radius:12px;box-shadow:0 12px 30px rgba(0,0,0,.12)}
.fc-nav li:hover>ul,.fc-nav li:focus-within>ul{display:flex}
.fc-nav li.has-submenu>a:after{content:'⌄';font-size:12px;margin-inline-start:7px}
.fc-nav li ul li ul{top:0;right:100%}
.fc-nav li ul a{white-space:nowrap;border-radius:8px}
.fc-drawer-nav ul{list-style:none;margin:0;padding:0}
.fc-drawer-nav li ul{display:none;padding-inline-start:14px;border-inline-start:2px solid var(--line);margin-inline-start:12px}
.fc-drawer-nav li.submenu-open>ul{display:block}
.fc-drawer-nav li.has-submenu>a:after{content:'＋';float:left;font-size:13px}
.fc-drawer-nav li.submenu-open>a:after{content:'−'}
.fc-nav a,.fc-drawer-nav a{display:block;padding:8px 14px;border-radius:999px;color:var(--ink);font-weight:500;font-size:16px}
.fc-nav a:hover,.fc-drawer-nav a:hover{background:color-mix(in srgb,var(--blue) 10%,transparent);text-decoration:none}
.fc-nav .is-current a,.fc-drawer-nav .is-current a{background:var(--grad);color:#fff}
.fc-acts{display:flex;align-items:center;gap:8px;margin-inline-start:auto}
.fc-search{display:flex;align-items:center;background:var(--bg);border:1px solid var(--line);border-radius:999px;padding-inline-start:14px;transition:border-color .2s,box-shadow .2s}
.fc-search:focus-within{border-color:var(--blue);box-shadow:0 0 0 3px color-mix(in srgb,var(--cyan) 35%,transparent)}
.fc-search input{border:0;background:transparent;color:var(--ink);font:inherit;font-size:15px;width:180px;padding:8px 4px;outline:0}
.fc-search input::placeholder{color:var(--muted)}
.ib{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;border:1px solid transparent;background:transparent;color:var(--ink);cursor:pointer;font:inherit}
.ib:hover{background:color-mix(in srgb,var(--blue) 10%,transparent)}
.fc-search .ib{width:36px;height:36px}
.i-sun{display:none}[data-theme=dark] .i-sun{display:block}[data-theme=dark] .i-moon{display:none}
#fc-menu{display:none}#fc-menu .i-x{display:none}#fc-menu[aria-expanded=true] .i-x{display:block}#fc-menu[aria-expanded=true] .i-m{display:none}
.fc-drawer{position:fixed;inset:var(--hh) 0 0 0;z-index:99;background:var(--surface);padding:20px;overflow:auto;border-top:1px solid var(--line)}
.fc-drawer[hidden]{display:none}
.fc-drawer .fc-search{margin-bottom:16px}.fc-drawer .fc-search input{width:100%;flex:1}
.fc-drawer-nav ul{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.fc-drawer-nav>.fc-mobile-home{display:block;padding:12px 16px;border-radius:12px;color:var(--ink);font-size:18px;font-weight:600}
.fc-drawer-nav>.fc-mobile-home:hover{background:color-mix(in srgb,var(--blue) 10%,transparent);text-decoration:none}
.fc-drawer-nav a{font-size:18px;padding:12px 16px;border-radius:12px}

/* Layout */
.fc-main-wrap{padding-block:28px 56px}
.fc-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;align-items:start}
.fc-layout:has(.fc-hero){grid-template-columns:minmax(0,1fr)}
.fc-layout:has(.fc-hero) .fc-side{display:none}
body.fc-error_page .fc-side{display:none}
body.fc-error_page .fc-layout{grid-template-columns:minmax(0,1fr)}
.fc-side{display:grid;gap:20px;position:sticky;top:calc(var(--hh) + 20px)}
.widget{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:20px;margin:0}
.widget-title{margin:0 0 14px;font-size:18px;font-weight:700;position:relative;padding-inline-start:14px;line-height:1.4}
.widget-title::before{content:"";position:absolute;inset-inline-start:0;top:.2em;bottom:.2em;width:4px;border-radius:4px;background:var(--grad)}
.fc-pop{list-style:none;margin:0;padding:0;counter-reset:p;display:grid;gap:12px}
.fc-pop li{counter-increment:p;display:flex;gap:12px;align-items:flex-start;line-height:1.6}
.fc-pop li::before{content:counter(p);flex:none;width:28px;height:28px;border-radius:8px;background:var(--grad);color:#fff;font-weight:700;font-size:14px;display:grid;place-items:center}
.fc-pop a{color:var(--ink);font-weight:500}
.fc-labs{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.fc-labs a{display:inline-flex;gap:8px;align-items:center;padding:6px 12px;border:1px solid var(--line);border-radius:999px;color:var(--ink);font-size:14px}
.fc-labs a:hover{border-color:var(--blue);text-decoration:none;color:var(--link)}
.fc-labs small{color:var(--muted)}

/* Section heads */
.fc-sec{margin-top:34px}.fc-sec:first-of-type{margin-top:12px}.fc-sec-head{margin-bottom:16px}.fc-sec-t{font-size:clamp(21px,2vw,26px)}.fc-state{min-height:82px;display:flex;align-items:center;justify-content:center;background:color-mix(in srgb,var(--surface) 78%,var(--bg));font-size:15px}
.fc-sec-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:20px;flex-wrap:wrap}
.fc-sec-t{margin:0;font-size:26px;line-height:1.4;font-weight:700;position:relative;padding-inline-start:16px}
.fc-sec-t::before{content:"";position:absolute;inset-inline-start:0;top:.25em;bottom:.25em;width:5px;border-radius:5px;background:var(--grad)}
.fc-sec-sub{margin:4px 0 0;color:var(--muted);font-size:15px}
.fc-more{font-weight:600;font-size:15px;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.fc-more .ico{width:18px;height:18px}
.fc-state{color:var(--muted);margin:0;padding:24px;text-align:center;border:1px dashed var(--line);border-radius:var(--r)}

/* Cards */
.fc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.fc-grid4{grid-template-columns:repeat(4,minmax(0,1fr))}
.fc-grid:not(:has(.fc-card))+.fc-empty{display:block}
.fc-empty{display:none;text-align:center;padding:48px 20px;background:var(--surface);border:1px dashed var(--line);border-radius:var(--r);color:var(--muted)}
.fc-card{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;transition:transform .2s,box-shadow .2s}
.fc-card:hover{transform:translateY(-3px);box-shadow:var(--shadow)}
.fc-thumb{display:block;aspect-ratio:16/9;background:linear-gradient(135deg,#e6efff,#dff8ff);overflow:hidden;position:relative}
[data-theme=dark] .fc-thumb{background:linear-gradient(135deg,#14224a,#0e2f45)}
.fc-thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s}
.fc-card:hover .fc-thumb img{transform:scale(1.04)}
.fc-ph{position:absolute;inset:0;background:var(--sym) center/22% no-repeat;opacity:.55}
.fc-body{padding:16px 18px 18px;display:flex;flex-direction:column;gap:8px;flex:1}
.fc-chip{display:inline-block;align-self:flex-start;font-size:13px;font-weight:600;line-height:1;padding:6px 10px;border-radius:999px;background:color-mix(in srgb,var(--blue) 12%,transparent);color:var(--link)}
.fc-chip:hover{text-decoration:none;background:color-mix(in srgb,var(--blue) 20%,transparent)}
.fc-t{margin:0;font-size:19px;line-height:1.55;font-weight:700}
.fc-t a{color:var(--ink);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.fc-t a:hover{color:var(--link);text-decoration:none}
.fc-snip{margin:0;color:var(--muted);font-size:15px;line-height:1.75;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.fc-meta{margin-top:auto;padding-top:6px;font-size:13.5px;color:var(--muted);display:flex;gap:12px;flex-wrap:wrap;align-items:center}

/* Hero */
.fc-hero{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:22px}
.fc-hero-main{position:relative;border-radius:calc(var(--r) + 4px);overflow:hidden;min-height:440px;display:flex;align-items:flex-end;background:linear-gradient(135deg,var(--navy),#0a3b9c);grid-row:span 2}
.fc-hero-main .fc-hero-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.fc-hero-main::after{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(5,12,34,.92) 0%,rgba(5,12,34,.45) 50%,rgba(5,12,34,.05) 100%)}
.fc-hero-txt{position:relative;z-index:1;padding:32px;color:#fff;display:grid;gap:12px;max-width:760px}
.fc-hero-txt .fc-chip{background:var(--grad);color:#fff}
.fc-hero-t{margin:0;font-size:clamp(24px,3.2vw,38px);line-height:1.45;font-weight:700}
.fc-hero-t a{color:#fff}
.fc-hero-t a::before{content:"";position:absolute;inset:0;z-index:2}
.fc-hero-txt .fc-snip{color:#d6e0f7;-webkit-line-clamp:2}
.fc-hero-txt .fc-meta{color:#c4d1ee;padding:0}
.fc-hero-side{display:contents}
.fc-hero-side .fc-card{flex-direction:row;align-items:stretch}
.fc-hero-side .fc-thumb{width:42%;aspect-ratio:auto;min-height:150px;flex:none}
.fc-hero-side .fc-t{font-size:17px}

/* Lists, pager */
.fc-listhead{margin-bottom:24px}
.fc-listhead h1{margin:8px 0 4px;font-size:clamp(26px,3.4vw,36px);line-height:1.4}
.fc-listhead p{margin:0;color:var(--muted)}
.fc-bc{font-size:14px;color:var(--muted);margin-bottom:14px}
.fc-bc ol{list-style:none;display:flex;flex-wrap:wrap;gap:6px;margin:0;padding:0}
.fc-bc li+li::before{content:"‹";margin-inline-end:6px;color:var(--muted)}
.fc-bc a{color:var(--muted)}.fc-bc a:hover{color:var(--link)}
.fc-bc [aria-current]{color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:46ch;display:inline-block;vertical-align:bottom}
.fc-pager{display:flex;justify-content:space-between;gap:12px;margin-top:32px;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;gap:8px;padding:11px 20px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font:600 15px var(--font);cursor:pointer}
.btn:hover{border-color:var(--blue);color:var(--link);text-decoration:none}
.btn-p{background:var(--grad);color:#fff;border-color:transparent}
.btn-p:hover{color:#fff;filter:brightness(1.06)}
.btn .ico{width:18px;height:18px}

/* Article */
.fc-article,.fc-pagebox{background:var(--surface);border:1px solid var(--line);border-radius:calc(var(--r) + 4px);padding:clamp(20px,4vw,44px)}
.fc-title{margin:10px 0 14px;font-size:clamp(28px,4vw,42px);line-height:1.45;font-weight:700}
.fc-pmeta{display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;color:var(--muted);font-size:14.5px;padding-bottom:20px;border-bottom:1px solid var(--line);margin-bottom:26px}
.fc-pmeta .au{display:inline-flex;gap:8px;align-items:center;color:var(--ink);font-weight:600}
.fc-pmeta img{width:28px;height:28px;border-radius:50%;object-fit:cover}
.fc-chips{display:flex;gap:8px;flex-wrap:wrap}
.post-body{font-size:18.5px;line-height:2;overflow-wrap:anywhere}
.post-body h2,.post-body h3,.post-body h4{line-height:1.5;margin:1.8em 0 .6em}
.post-body h2{font-size:1.6em}.post-body h3{font-size:1.3em}
.post-body p{margin:0 0 1.2em}
.post-body img{height:auto;border-radius:12px}
.post-body .separator,.post-body .tr-caption-container{text-align:center!important}
.post-body a{text-decoration:underline;text-underline-offset:3px}
.post-body blockquote{margin:1.6em 0;padding:14px 22px;border-inline-start:4px solid var(--blue);background:color-mix(in srgb,var(--blue) 7%,transparent);border-radius:0 12px 12px 0;color:var(--ink)}
.post-body pre,.post-body code{direction:ltr;text-align:left;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:.88em}
.post-body pre{background:#0b1430;color:#e6edff;padding:16px;border-radius:12px;overflow:auto}
.post-body :not(pre)>code{background:color-mix(in srgb,var(--blue) 10%,transparent);padding:2px 6px;border-radius:6px}
.post-body table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%}
.post-body th,.post-body td{border:1px solid var(--line);padding:8px 12px}
.post-body iframe{max-width:100%}
.fc-foot{margin-top:32px;padding-top:22px;border-top:1px solid var(--line);display:grid;gap:22px}
.fc-share{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.fc-share strong{margin-inline-end:6px}
.fc-share a,.fc-share button{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:999px;border:1px solid var(--line);background:var(--bg);color:var(--ink);font:500 14px var(--font);cursor:pointer}
.fc-share a:hover,.fc-share button:hover{border-color:var(--blue);color:var(--link);text-decoration:none}
.fc-share .ico{width:16px;height:16px}
.fc-share [hidden]{display:none}
.fc-author{display:flex;gap:16px;align-items:center;padding:18px;border:1px solid var(--line);border-radius:var(--r);background:var(--bg)}
.fc-author img{width:60px;height:60px;border-radius:50%;object-fit:cover;flex:none}
.fc-author b{display:block;font-size:17px}.fc-author p{margin:2px 0 0;color:var(--muted);font-size:15px;line-height:1.7}
.fc-small{font-size:13.5px;color:var(--muted)}
.fc-related{margin-top:40px}
.fc-comments{margin-top:40px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:clamp(18px,3vw,32px)}
.fc-comments h2,.fc-comments h4,.fc-comments h3{margin-top:0}
.fc-comments a{text-decoration:underline}
.fc-comments iframe{width:100%;border:0;min-height:300px}
.fc-comments .comments .comment-author{font-weight:700}
.fc-comments ol,.fc-comments ul{padding-inline-start:0;list-style:none}
.fc-comments .comment-replies{margin-inline-start:20px}
.fc-comments .comment-actions a{margin-inline-end:12px;font-size:14px}

/* Error */
.fc-err{text-align:center;padding:56px 20px;background:var(--surface);border:1px solid var(--line);border-radius:calc(var(--r) + 4px)}
.fc-404{font-size:clamp(72px,16vw,140px);font-weight:700;line-height:1;margin:0;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.fc-err h1{margin:12px 0 8px;font-size:28px}.fc-err p{color:var(--muted);max-width:52ch;margin:0 auto 22px}
.fc-err .fc-search{max-width:420px;margin:0 auto 22px}.fc-err .fc-search input{flex:1;width:100%}

/* Footer */
.fc-footer{background:$(footer.bg);color:#c9d5f0;margin-top:24px;padding-top:48px}
.fc-foot-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:36px;padding-bottom:36px}
.fc-footer .fc-brand{--wm:#fff;font-size:32px}
.fc-footer .widget{background:transparent;border:0;padding:0}
.fc-footer .widget-title{color:#fff}
.fc-footer .widget-content,.fc-footer p{font-size:15px;line-height:1.9;margin:14px 0 0}
.fc-footer ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.fc-footer a{color:#c9d5f0}.fc-footer a:hover{color:#fff}
.fc-footer .fc-labs a{border-color:#22305a;color:#c9d5f0}.fc-footer .fc-labs small{color:#8fa0c7}
.fc-bottom{border-top:1px solid #1a2a52;padding-block:18px;font-size:14px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:#9fb0d3}
.fc-copyright{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.fc-bottom .fc-copyright-brand{--wm:#fff;font-size:19px}
#fc-toast{position:fixed;inset-inline:0;bottom:24px;margin-inline:auto;width:max-content;max-width:90vw;background:var(--navy);color:#fff;padding:10px 18px;border-radius:999px;font-size:15px;opacity:0;transform:translateY(12px);pointer-events:none;transition:.25s;z-index:300}
[data-theme=dark] #fc-toast{background:#e9eefb;color:#0a1020}
#fc-toast.show{opacity:1;transform:none}

/* Responsive */
@media (max-width:1100px){.fc-grid4{grid-template-columns:repeat(2,minmax(0,1fr))}.fc-layout{grid-template-columns:minmax(0,1fr) 280px;gap:24px}}
@media (max-width:900px){
.fc-nav,.fc-home-link,.fc-acts .fc-search{display:none}#fc-menu{display:inline-flex}
.fc-layout,.fc-layout:has(.fc-hero){grid-template-columns:minmax(0,1fr)}.fc-side{position:static}
.fc-layout:has(.fc-hero) .fc-side{display:none}
.fc-hero{grid-template-columns:minmax(0,1fr)}.fc-hero-main{grid-row:auto;min-height:380px}
.fc-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.fc-foot-grid{grid-template-columns:1fr 1fr}.fc-foot-grid>:first-child{grid-column:1/-1}}
@media (max-width:600px){
body{font-size:16px}.fc-wrap{padding-inline:16px}.fc-brand{font-size:26px}
.fc-grid,.fc-grid4{grid-template-columns:minmax(0,1fr)}
.fc-hero-main{min-height:340px}.fc-hero-txt{padding:20px}.fc-hero-txt .fc-snip{display:none}
.fc-hero-side .fc-thumb{width:38%}
.fc-sec-t{font-size:22px}.post-body{font-size:17.5px}
.fc-foot-grid{grid-template-columns:1fr}.fc-author{flex-direction:column;text-align:center}
.fc-pager .btn{flex:1;justify-content:center}}
@media (prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}.fc-card:hover{transform:none}}
@media print{.fc-header,.fc-side,.fc-footer,.fc-share,.fc-related,.fc-comments,.fc-pager{display:none!important}.fc-layout{display:block}}


/* ===== v2: layout-driven gadgets, banner, social, sections ===== */
.fc-cfgwrap,#herobanner .widget,#homesections .widget,#brandsettings .widget{display:none}
.fc-brand [hidden]{display:none}
.fc-brand.is-custom{direction:rtl;gap:10px}
.fc-brand.is-custom img{height:40px;width:auto;margin:0}
.fc-hero[hidden]{display:none}
.fc-banner{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);align-items:center;gap:28px;padding:clamp(24px,5vw,56px);border-radius:calc(var(--r) + 8px);background:linear-gradient(135deg,var(--navy) 0%,#0a3b9c 62%,var(--blue) 100%);color:#fff;margin-bottom:28px;position:relative;overflow:hidden}
.fc-banner:not(.has-img){grid-template-columns:minmax(0,1fr)}
.fc-banner.is-center{text-align:center;justify-items:center}
.fc-banner .fc-chip{background:var(--grad);color:#fff}
.fc-banner-t{margin:12px 0 10px;font-size:clamp(28px,4.2vw,46px);line-height:1.4;font-weight:700}
.fc-banner-d{margin:0 0 24px;color:#d6e0f7;font-size:18px;max-width:60ch}
.fc-banner.is-center .fc-banner-d{margin-inline:auto}
.fc-banner-btns{display:flex;gap:12px;flex-wrap:wrap}
.fc-banner.is-center .fc-banner-btns{justify-content:center}
.fc-banner .btn:not(.btn-p){background:rgba(255,255,255,.1);color:#fff;border-color:rgba(255,255,255,.35)}
.fc-banner .btn:not(.btn-p):hover{background:rgba(255,255,255,.2)}
.fc-banner-img img{width:100%;height:auto;border-radius:16px;display:block}
.fc-sec:first-child{margin-top:0}
.fc-hero+.fc-sec,.fc-sec{margin-top:48px}
.fc-grid[data-n="1"]{grid-template-columns:minmax(0,1fr)}
.fc-grid[data-n="2"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.fc-grid[data-n="3"]{grid-template-columns:repeat(3,minmax(0,1fr))}
.fc-grid[data-n="4"]{grid-template-columns:repeat(4,minmax(0,1fr))}
.fc-list{grid-template-columns:repeat(2,minmax(0,1fr))}
.fc-list .fc-card{flex-direction:row}
.fc-list .fc-thumb{width:38%;aspect-ratio:auto;min-height:150px;flex:none}
.fc-list .fc-snip{-webkit-line-clamp:2}
.fc-clist{list-style:none;margin:0;padding:0;background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
.fc-clist li{display:flex;justify-content:space-between;gap:16px;align-items:baseline;padding:14px 18px;border-bottom:1px solid var(--line)}
.fc-clist li:last-child{border-bottom:0}
.fc-clist a{color:var(--ink);font-weight:600}.fc-clist time{color:var(--muted);font-size:13.5px;white-space:nowrap}
.fc-state .btn{margin-inline-start:10px;padding:6px 14px}
.fc-social{list-style:none;margin:0;padding:0;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.fc-social:empty{display:none}
.fc-social a{display:inline-flex;align-items:center;justify-content:center;min-width:38px;min-height:38px;border-radius:999px;border:1px solid var(--line);color:var(--ink);padding:0 10px;font-size:14px}
.fc-social a.is-icon{width:38px;padding:0}
.fc-social a:hover{border-color:var(--blue);color:var(--link);text-decoration:none}
.fc-hdrsoc{display:flex}.fc-hdrsoc .fc-social a{border-color:transparent;width:36px;min-width:36px;min-height:36px;height:36px}
.fc-footer .fc-social{margin-top:16px}
.fc-footer .fc-social a{color:#c9d5f0;border-color:#22305a}.fc-footer .fc-social a:hover{color:#fff;border-color:var(--cyan)}
.fc-drawer>.fc-social{margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}
.fc-tw{overflow-x:auto;margin:1.4em 0;border:1px solid var(--line);border-radius:12px;-webkit-overflow-scrolling:touch}
.fc-tw table,.post-body .fc-tw table{display:table;width:100%;min-width:520px;margin:0;border:0;font-size:.92em;line-height:1.7}
.post-body th{background:color-mix(in srgb,var(--blue) 10%,transparent);text-align:start;font-weight:700}
.post-body tbody tr:nth-child(even){background:color-mix(in srgb,var(--blue) 4%,transparent)}
.fc-tw th,.fc-tw td{border-width:0 0 1px 0}.fc-tw tr:last-child td{border-bottom:0}
.fc-pre{position:relative;margin:1.4em 0}.fc-pre pre{margin:0;padding-top:42px}
.fc-copy{position:absolute;top:8px;inset-inline-end:8px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);color:#e6edff;border-radius:8px;padding:4px 12px;font:500 13px var(--font);cursor:pointer}
.fc-copy:hover{background:rgba(255,255,255,.18)}
@media (max-width:1100px){.fc-grid[data-n="4"]{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:900px){.fc-grid[data-n="3"]{grid-template-columns:repeat(2,minmax(0,1fr))}.fc-banner{grid-template-columns:minmax(0,1fr)}.fc-hdrsoc{display:none}.fc-list{grid-template-columns:minmax(0,1fr)}}
@media (max-width:600px){.fc-grid[data-n]{grid-template-columns:minmax(0,1fr)}.fc-banner-btns .btn{flex:1;justify-content:center}.fc-list .fc-thumb{width:34%}.fc-clist li{flex-direction:column;gap:2px}}

/* FAR CODO DESIGN SYSTEM — V1 2026 */
:root{--fc-blue:#0878f9;--fc-blue2:#05a5ff;--fc-navy:#031f36;--fc-ink:#102d4b;--fc-muted:#647a91;--fc-line:#dce9f7;--fc-soft:#f3f8fe;--fc-card:#fff;--fc-radius:15px;--fc-shadow:0 8px 26px rgba(11,57,103,.075)}
html{scroll-behavior:smooth}
body{background:linear-gradient(180deg,#f4f9ff 0,#fff 340px,#f6faff 100%);color:var(--fc-ink);font-family:Tahoma,Arial,sans-serif}
a{transition:color .2s ease,background .2s ease,transform .2s ease}
a:hover{color:var(--fc-blue)}
img{max-width:100%;height:auto}
.fc-header,.header-wrapper,.header-inner{background:#fff}
.fc-header{box-shadow:0 5px 24px rgba(8,48,86,.06);border-bottom:1px solid #e8f0fa;position:relative;z-index:20}
.fc-top,.fc-topbar,.topbar{background:linear-gradient(100deg,#031c30,#063653);color:#eaf5ff}
.fc-header .widget,.fc-nav .widget,.fc-hdrsoc .widget{margin:0}
.fc-nav{font-weight:700}
.fc-nav a{font-size:13px}
.fc-brandsec img,.fc-logo img,.header-logo img{max-height:62px;width:auto;object-fit:contain}
.fc-banner,.fc-hero,.fc-herosec .widget-content{border-radius:var(--fc-radius);overflow:hidden}
.fc-banner{box-shadow:0 12px 30px rgba(0,53,104,.13);border:1px solid rgba(255,255,255,.5)}
.fc-banner h1,.fc-banner h2{line-height:1.45;letter-spacing:-.3px}
.fc-banner p{line-height:1.9}
.fc-banner .btn,.fc-banner-btns .btn,.button{border-radius:999px;background:linear-gradient(110deg,var(--fc-blue),#0056d8);box-shadow:0 5px 14px rgba(0,105,245,.23);font-weight:700}
.fc-homesec .widget,.fc-category,.fc-cat-card,.fc-card,.post-outer,.post{border-radius:12px}
.fc-homesec .widget{background:#fff;border:1px solid #e3edf8;box-shadow:var(--fc-shadow);padding:12px;transition:transform .22s ease,box-shadow .22s ease}
.fc-homesec .widget:hover,.post-outer:hover{transform:translateY(-3px);box-shadow:0 13px 28px rgba(11,57,103,.11)}
.fc-homesec .widget img,.fc-grid img,.fc-list img{border-radius:9px}
.fc-section-title,.fc-listhead,.widget-title{color:var(--fc-ink);font-weight:800}
.fc-section-title:after,.widget-title:after{content:"";display:block;width:42px;height:3px;margin-top:8px;border-radius:5px;background:linear-gradient(90deg,var(--fc-blue),#78caff)}
.fc-mainsec,.fc-sidesec{min-width:0}
.fc-sidesec .widget{background:#fff;border:1px solid #e1edf9;border-radius:13px;padding:14px;box-shadow:var(--fc-shadow);margin-bottom:16px}
.fc-sidesec .widget img{border-radius:9px}
.fc-grid{gap:14px}
.fc-grid .post-outer,.fc-grid .post{background:#fff;border:1px solid #e4edf7;box-shadow:0 4px 15px rgba(10,52,92,.045);padding:10px;border-radius:12px}
.fc-grid .post-title,.fc-list .post-title{font-size:15px;line-height:1.8;font-weight:800}
.fc-grid .post-title a,.fc-list .post-title a{color:#102d4b}
.fc-grid .post-title a:hover,.fc-list .post-title a:hover{color:var(--fc-blue)}
.fc-meta,.post-footer,.post-header{color:var(--fc-muted);font-size:12px}
.fc-footer,.footer-wrapper,.footer{background:linear-gradient(125deg,#031b2e,#07324d);color:#eaf5ff}
.fc-footer a,.footer-wrapper a,.footer a{color:#d5eaff}
.fc-footer a:hover,.footer-wrapper a:hover,.footer a:hover{color:#42b5ff}
.fc-footer .widget,.footer-wrapper .widget{background:transparent;border:0;box-shadow:none}
.fc-footer-bottom{border-top:1px solid rgba(255,255,255,.17)}
input,textarea,select{border-radius:10px!important;border:1px solid #dce8f6!important}
button,input[type=submit]{border-radius:999px}
:focus-visible{outline:3px solid rgba(0,126,255,.45);outline-offset:3px}
@media(min-width:1100px){.content-wrapper,.outer-wrapper{max-width:1200px}}
@media(max-width:900px){.fc-banner{border-radius:12px}.fc-homesec .widget{padding:10px}.fc-sidesec .widget{padding:12px}}
@media(max-width:600px){body{font-size:14px}.fc-banner h1,.fc-banner h2{font-size:25px;line-height:1.5}.fc-banner p{font-size:13px}.fc-homesec .widget{border-radius:11px}.fc-grid{gap:10px}.fc-grid .post-outer,.fc-grid .post{padding:8px}.fc-footer{padding-top:24px}}


/* Top bar, CTA and V1 release signature */
.fc-topbar{background:linear-gradient(100deg,#031b2e,#073653);color:#eaf5ff;font-size:12px}
.fc-topbar-inner{min-height:38px;display:flex;align-items:center;justify-content:space-between;gap:16px}
.fc-topbar p{display:flex;align-items:center;gap:8px;margin:0}
.fc-topbar .ico{width:15px;height:15px;vertical-align:middle}
.fc-topbar a{display:inline-flex;align-items:center;gap:6px;color:#eaf5ff;text-decoration:none;font-weight:700}
.fc-topbar a:hover{color:#62c1ff}
.fc-start-wrap{padding:0 0 28px}
.fc-start{display:flex;align-items:center;gap:18px;padding:20px 24px;border:1px solid #dbeafa;border-radius:14px;background:linear-gradient(110deg,#f1f8ff,#fff);box-shadow:0 5px 20px rgba(11,57,103,.045)}
.fc-start-icon{display:grid;place-items:center;flex:0 0 58px;width:58px;height:58px;border-radius:16px;background:#e0f0ff;color:#0878f9}
.fc-start-icon svg{width:38px;height:38px}
.fc-start-copy{flex:1;min-width:0}
.fc-start h2{margin:0 0 5px;font-size:19px;color:#102d4b}
.fc-start p{margin:0;color:#647a91;font-size:13px;line-height:1.8}
.fc-start .btn{white-space:nowrap}
.fc-version{font-size:11px;color:#b9d5ed;letter-spacing:.15px}
.fc-bottom{gap:14px}
@media(max-width:600px){.fc-topbar-inner{min-height:34px}.fc-topbar p{font-size:11px}.fc-topbar a{font-size:11px}.fc-start{align-items:flex-start;flex-wrap:wrap;padding:16px;gap:12px}.fc-start-icon{width:44px;height:44px;flex-basis:44px;border-radius:12px}.fc-start-icon svg{width:30px;height:30px}.fc-start-copy{flex:1 1 calc(100% - 60px)}.fc-start h2{font-size:17px}.fc-start .btn{width:100%;justify-content:center}.fc-version{order:3;width:100%;text-align:center}}


/* Accessibility and active navigation polish — Farcodo V1 / 2026 */
.skip{position:fixed;z-index:9999;top:8px;right:8px;transform:translateY(-160%);padding:12px 18px;border-radius:10px;background:#0878f9;color:#fff!important;font-weight:800;box-shadow:0 5px 18px rgba(0,0,0,.18)}
.skip:focus{transform:translateY(0);outline:3px solid #fff;outline-offset:2px}
.fc-nav a[aria-current=page]{background:linear-gradient(110deg,#0878f9,#0758d5);color:#fff;box-shadow:0 4px 12px rgba(8,120,249,.18)}
.fc-nav li.is-current>a{color:#fff}
.fc-drawer-nav a[aria-current=page]{background:linear-gradient(110deg,#0878f9,#0758d5);color:#fff}
.fc-brand{flex-shrink:0}
.fc-brand img{object-fit:contain}
.fc-social a:focus-visible,.fc-nav a:focus-visible,.fc-drawer-nav a:focus-visible,.fc-more:focus-visible{outline:3px solid rgba(8,120,249,.55);outline-offset:3px}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

body.script:
//
/* Farcodo Arabic — original script. No third-party libraries, no tracking. */
(function () {
  'use strict';
  var d = document;
  function $(s, c) { return (c || d).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); }
  function el(t, c, x) { var e = d.createElement(t); if (c) e.className = c; if (x != null) e.textContent = x; return e; }

  var T = {
    copied: 'تم نسخ الرابط', copyFail: 'تعذّر نسخ الرابط',
    loading: 'جارٍ تحميل المقالات…', err: 'تعذّر تحميل المقالات حاليًا. حاول مرة أخرى لاحقًا.',
    empty: 'لا توجد مقالات في هذا القسم بعد.', noRel: 'لا توجد مقالات ذات صلة حاليًا.',
    all: 'عرض كل المقالات', read: 'وقت القراءة', upd: 'آخر تحديث',
    dark: 'التبديل إلى الوضع الفاتح', light: 'التبديل إلى الوضع الداكن',
    open: 'فتح القائمة', close: 'إغلاق القائمة', retry: 'إعادة المحاولة',
    copy: 'نسخ', copied2: 'تم النسخ', tbl: 'جدول قابل للتمرير'
  };

  function mins(n) {
    n = Math.max(1, Math.round(n));
    if (n === 1) return 'دقيقة واحدة';
    if (n === 2) return 'دقيقتان';
    if (n <= 10) return n + ' دقائق';
    return n + ' دقيقة';
  }
  function fmt(iso) {
    try { return new Date(iso).toLocaleDateString('ar-u-nu-latn', { year: 'numeric', month: 'long', day: 'numeric' }); }
    catch (e) { return ''; }
  }
  function strip(h) {
    try { return (new DOMParser().parseFromString(h || '', 'text/html').body.textContent || '').replace(/\s+/g, ' ').trim(); }
    catch (e) { return ''; }
  }
  function bigImg(u) {
    return u ? u.replace(/\/s\d+(-[a-z]+)*\//, '/w640-h360-c/').replace(/=s\d+(-[a-z]+)*$/, '=w640-h360-c') : '';
  }
  function pathKey(u) { return String(u || '').replace(/^https?:\/\/[^\/]+/, '').split(/[?#]/)[0]; }

  var tt;
  function toast(m) {
    var t = $('#fc-toast'); if (!t) return;
    t.textContent = m; t.classList.add('show');
    clearTimeout(tt); tt = setTimeout(function () { t.classList.remove('show'); }, 2200);
  }

  /* ---------- Theme ---------- */
  function syncTheme() {
    var t = d.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
    var b = $('#fc-theme');
    if (b) { b.setAttribute('aria-pressed', t === 'dark' ? 'true' : 'false'); b.setAttribute('aria-label', t === 'dark' ? T.dark : T.light); }
  }
  function initTheme() {
    var b = $('#fc-theme'); syncTheme();
    if (!b) return;
    b.addEventListener('click', function () {
      var n = d.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      d.documentElement.setAttribute('data-theme', n);
      try { localStorage.setItem('fc-theme', n); } catch (e) {}
      syncTheme();
    });
  }

  /* ---------- Header menu dropdowns ---------- */
  function buildMenuTree(root) {
    if (!root || root.getAttribute('data-tree-ready') === '1') return;
    var items = Array.prototype.slice.call(root.children).filter(function (el) { return el.tagName === 'LI'; });
    var stack = [];
    items.forEach(function (li) {
      var a = li.querySelector(':scope > a');
      if (!a) return;
      var label = (a.textContent || '').trim();
      var match = label.match(/^(--|-)[ \u00a0]+/);
      var depth = match ? (match[1] === '--' ? 2 : 1) : 0;
      if (depth === 0) { stack = [li]; return; }
      a.textContent = label.replace(/^(--|-)[ \u00a0]+/, '');
      var parent = stack[depth - 1];
      if (!parent) { stack[depth] = li; return; }
      var sub = parent.querySelector(':scope > ul');
      if (!sub) { sub = d.createElement('ul'); parent.appendChild(sub); }
      parent.classList.add('has-submenu');
      sub.appendChild(li);
      stack[depth] = li;
      stack.length = depth + 1;
    });
    root.setAttribute('data-tree-ready', '1');
  }
  function initHeaderMenus() {
    var nav = $('.fc-nav ul');
    buildMenuTree(nav);
    if (!nav) return;
    var current = pathKey(location.href).replace(/\/$/, '') || '/';
    $('a', nav).forEach(function (a) {
      var href = a.getAttribute('href') || '';
      if (!/^https?:/i.test(href) && href.charAt(0) !== '/') return;
