    if (p.img) { var im = new Image(); im.alt = ''; im.width = 640; im.height = 360; im.loading = 'lazy'; im.decoding = 'async'; im.src = p.img; th.appendChild(im); }
    else th.appendChild(el('span', 'fc-ph'));
