       exist, their order and settings remain fully controlled from Layout. */
    /* No fixed category defaults: buyers add their own section gadgets in Blogger Layout. */
    return found;
  }
  function yes(v) { return /^(yes|true|1|نعم)$/i.test((v || '').trim()); }
  function safeUrl(u) {
