    youtube: "<rect x='3' y='6' width='18' height='12' rx='3.5'/><path d='M10.4 9.4v5.2l4.4-2.6z' fill='currentColor'/>",
    linkedin: "<circle cx='6.6' cy='7' r='1.4' fill='currentColor' stroke='none'/><path d='M5.4 10.2h2.6V19H5.4zM10.4 10.2h2.5v1.2c.5-.9 1.5-1.4 2.7-1.4 2.3 0 3.4 1.4 3.4 3.9V19h-2.6v-4.6c0-1.2-.5-1.9-1.5-1.9s-1.8.7-1.8 1.9V19h-2.7z' fill='currentColor' stroke='none'/>",
    telegram: "<path d='M20.5 4.5L3.5 11l5 1.8 2 5.6 2.8-3.4 4.4 3.2z'/><path d='M8.5 12.8l8-5.6'/>",
    whatsapp: "<path d='M4.5 19.5l1.2-4A8 8 0 1 1 9 18.6z'/><path d='M9.3 8.8c.3 2.6 2.6 4.9 5.2 5.2l1.2-1.3-1.9-1-.8.7c-.9-.4-1.5-1-1.9-1.9l.7-.8-1-1.9z' fill='currentColor' stroke='none'/>",
    tiktok: "<path d='M13.5 4v10.2a3.3 3.3 0 1 1-3.3-3.3M13.5 4c.3 2.2 1.8 3.7 4 3.9'/>",
    email: "<rect x='3.5' y='5.5' width='17' height='13' rx='2.5'/><path d='M4 7.5l8 6 8-6'/>",
    rss: "<path d='M5 12a7 7 0 0 1 7 7M5 5.5A13.5 13.5 0 0 1 18.5 19'/><circle cx='6' cy='18' r='1.3' fill='currentColor'/>",
    link: "<path d='M10 14a4 4 0 005.7 0l3-3a4 4 0 00-5.7-5.7l-1 1M14 10a4 4 0 00-5.7 0l-3 3a4 4 0 005.7 5.7l1-1'/>"
  };
  function iconKey(h) {
    h = (h || '').toLowerCase();
    if (/^mailto:/.test(h)) return 'email';
    if (/\/feeds\/|\.rss|\/rss/.test(h)) return 'rss';
    if (/(^|\/\/|\.)(facebook|fb)\.com/.test(h)) return 'facebook';
    if (/(^|\/\/|\.)(twitter|x)\.com/.test(h)) return 'x';
    if (/instagram\.com/.test(h)) return 'instagram';
    if (/youtube\.com|youtu\.be/.test(h)) return 'youtube';
    if (/linkedin\.com/.test(h)) return 'linkedin';
    if (/(^|\/\/)t\.me|telegram\./.test(h)) return 'telegram';
    if (/wa\.me|whatsapp\./.test(h)) return 'whatsapp';
