  function social() {
    $$('.fc-social').forEach(function (ul) {
      if (!ul.children.length) { ul.hidden = true; return; }
      $$('a', ul).forEach(function (a) {
        var label = a.textContent.trim();
        if (!safeUrl(a.getAttribute('href'))) { a.parentNode.removeChild(a); return; }
        var svg = d.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 24 24'); svg.setAttribute('class', 'ico'); svg.setAttribute('aria-hidden', 'true');
        svg.innerHTML = ICONS[iconKey(a.getAttribute('href'))];
