    if ($('[data-kind=label]')) { ld({ '@context': 'https://schema.org', '@type': 'CollectionPage', name: ($('.fc-listhead h1') || {}).textContent || d.title, url: url, inLanguage: 'ar' }); var c2 = crumbs(); if (c2) ld(c2); }
  }

  function init() {
